use once_cell::sync::Lazy;
use std::env;

/// Picks the platform-specific shared-library extension.
fn get_extension(system: &str) -> &str {
    if system == "windows" {
        ".dll"
    } else if system == "macos" {
        ".dylib"
    } else {
        ".so"
    }
}

// DEVIATION FROM THE GENERATED DEFAULT (deliberate - this file is a vendored COPY, not a
// reference to the submodule, so we are free to edit this one function). The generated
// load_library() above hard-codes "./bin/CASBACnetStack_x64_Debug<ext>" - a Debug-named DLL
// under a "./bin/" path RELATIVE TO THE PROCESS'S CURRENT WORKING DIRECTORY. That assumes a
// Debug build layout that does not exist for this example: this project only ever builds/ships
// the stack's Release configuration (see README.md "Why only a Release build", matching the
// C#/Python siblings), and a relative "./bin/" path breaks the moment this example is launched
// from any directory other than the one that happens to contain a "bin" subfolder next to the
// DLL - e.g. `cargo run` from the crate root, or a double-click launch from Explorer.
//
// This vendored copy instead resolves CASBACnetStack_x64_Release{.dll,.so,.dylib} NEXT TO THE
// RUNNING EXECUTABLE (`std::env::current_exe()`'s parent directory), which is where the
// README/CI instruct you to copy it - the same convention the C#/Python editions use (the .NET
// native-library resolver and Python's `os.path.dirname(__file__)` lookup both search next to
// the running program first). If that resolution fails for any reason (e.g. current_exe() is
// unavailable on some exotic target), this falls back to the bare filename so the OS's normal
// shared-library search path (PATH / LD_LIBRARY_PATH / rpath) gets a chance.
fn load_library() -> libloading::Library {
    let filename = "CASBACnetStack_x64_Release".to_owned() + get_extension(env::consts::OS);
    let candidate = env::current_exe()
        .ok()
        .and_then(|exe| exe.parent().map(|dir| dir.join(&filename)));
    unsafe {
        if let Some(path) = candidate {
            if let Ok(lib) = libloading::Library::new(&path) {
                return lib;
            }
        }
        libloading::Library::new(&filename)
            .unwrap_or_else(|e| panic!("failed to load {filename} (checked next to the executable, then the OS library search path): {e}"))
    }
}

static LIBRARY: Lazy<libloading::Library> = Lazy::new(load_library);

