/// STACK_OPTION_DATA_LINK_LAYER_SC
///
/// Registered with [`BACnetStack_RegisterCallbackDisconnectWebsocket`].
///
/// C declaration: `void(*FPCallbackDisconnectWebsocket)(const char* websocketUri, const uint32_t
/// websocketUriLength)`
///
/// # Arguments
///
/// * `websocketUri` - The URI of the websocket to disconnect.
/// * `websocketUriLength` - The length of the websockerUri string.
pub type FPCallbackDisconnectWebsocket = extern "C" fn(*const std::os::raw::c_char, u32);

/// The FPCallbackSCStartListening callback gets called when the CAS BACnet Stack needs to start
/// listening
/// for inbound BACnet/SC websocket connections.
///
/// This callback is the application-layer boundary for inbound listener ownership. The stack
/// decides when BACnet/SC hub-function
/// or direct-connect accept mode should be active, but the application is responsible for binding
/// and running the actual listener,
/// including TLS configuration and certificate policy.
///
/// *Note:** This callback can only be used if the CAS BACnet Stack has been compiled with
/// STACK_OPTION_DATA_LINK_LAYER_SC
///
/// Registered with [`BACnetStack_RegisterCallbackSCStartListening`].
///
/// C declaration: `bool(*FPCallbackSCStartListening)(const char* websocketUri, const uint32_t
/// websocketUriLength)`
///
/// # Arguments
///
/// * `websocketUri` - The URI to listen on.
/// * `websocketUriLength` - The length of the websocketUri string.
///
/// # Returns
///
/// True if the user successfully started listening, otherwise false.
pub type FPCallbackSCStartListening = extern "C" fn(*const std::os::raw::c_char, u32) -> bool;

/// The FPCallbackSCStopListening callback gets called when the CAS BACnet Stack needs to stop
/// listening
/// for inbound BACnet/SC websocket connections.
///
/// This callback keeps listener shutdown in the application layer so the stack remains
/// independent from any specific websocket
/// or TLS implementation.
///
/// *Note:** This callback can only be used if the CAS BACnet Stack has been compiled with
/// STACK_OPTION_DATA_LINK_LAYER_SC
///
/// Registered with [`BACnetStack_RegisterCallbackSCStopListening`].
///
/// C declaration: `void(*FPCallbackSCStopListening)(const char* websocketUri, const uint32_t
/// websocketUriLength)`
///
/// # Arguments
///
/// * `websocketUri` - The URI to stop listening on.
/// * `websocketUriLength` - The length of the websocketUri string.
pub type FPCallbackSCStopListening = extern "C" fn(*const std::os::raw::c_char, u32);

/// The FPCallbackBACnetSCStateChange callback gets called when the CAS BACnet Stack changes an
/// observable
/// BACnet/SC state machine value.
///
/// This callback is intended for diagnostics only. The stack invokes it after updating its own
/// internal state.
///
/// *Note:** This callback can only be used if the CAS BACnet Stack has been compiled with
/// STACK_OPTION_DATA_LINK_LAYER_SC
///
/// Registered with [`BACnetStack_RegisterCallbackBACnetSCStateChange`].
///
/// C declaration: `void(*FPCallbackBACnetSCStateChange)(const uint32_t deviceInstance, const
/// uint32_t networkPortInstance, const uint8_t stateMachine, const uint8_t previousState, const
/// uint8_t newState, const char* websocketUri, const uint32_t websocketUriLength)`
///
/// # Arguments
///
/// * `deviceInstance` - The BACnet device instance associated with the BACnet/SC Network Port, or 0 when not
///   known.
/// * `networkPortInstance` - The BACnet/SC Network Port object instance associated with the transition, or 0 when
///   not known.
/// * `stateMachine` - The BACnet/SC state machine identifier. See
///   #CASBACnetStack::BACnetSCConstants::BACnetSCStateChangeStateMachines.
/// * `previousState` - The previous state value.
/// * `newState` - The new state value.
/// * `websocketUri` - The websocket URI associated with the transition, or NULL when not applicable.
/// * `websocketUriLength` - The websocket URI length.
pub type FPCallbackBACnetSCStateChange = extern "C" fn(u32, u32, u8, u8, u8, *const std::os::raw::c_char, u32);

/// The FPCallbackValidateBACnetSCOperationalCertificate callback gets called when the CAS BACnet
/// Stack
/// needs the application to perform real BACnet/SC operational-certificate validation during
/// VALIDATE_CHANGES processing.
///
/// The stack owns the BACnet Network Port object model and File-object contents, but the
/// application owns
/// the concrete TLS implementation and private key. This callback lets the application validate
/// that the
/// pending operational certificate is well-formed, trusted by the configured issuer certificates,
/// not
/// expired relative to the supplied timestamp, and matches the application's active private key.
///
/// *Note:** This callback can only be used if the CAS BACnet Stack has been compiled with
/// STACK_OPTION_DATA_LINK_LAYER_SC
///
/// Registered with [`BACnetStack_RegisterCallbackValidateBACnetSCOperationalCertificate`].
///
/// C declaration: `bool(*FPCallbackValidateBACnetSCOperationalCertificate)(const uint32_t
/// deviceInstance, const uint32_t networkPortInstance, const uint8_t*
/// operationalCertificateFileData, const uint32_t operationalCertificateFileDataLength, const
/// uint8_t* issuerCertificateFile1Data, const uint32_t issuerCertificateFile1DataLength, const
/// uint8_t* issuerCertificateFile2Data, const uint32_t issuerCertificateFile2DataLength, const
/// CASBACnetTime timestamp, uint32_t* failingPropertyIdentifier, char* details, uint32_t*
/// detailsLength, const uint32_t maxDetailsLength)`
///
/// # Arguments
///
/// * `deviceInstance` - The BACnet device instance that owns the BACnet/SC Network Port.
/// * `networkPortInstance` - The BACnet/SC Network Port object instance being validated.
/// * `operationalCertificateFileData` - The pending Operational_Certificate_File contents.
/// * `operationalCertificateFileDataLength` - The length of the operational certificate contents.
/// * `issuerCertificateFile1Data` - The first pending Issuer_Certificate_Files entry contents.
/// * `issuerCertificateFile1DataLength` - The length of the first issuer certificate contents.
/// * `issuerCertificateFile2Data` - The second pending Issuer_Certificate_Files entry contents.
/// * `issuerCertificateFile2DataLength` - The length of the second issuer certificate contents.
/// * `timestamp` - The timestamp that should be used for expiry/not-yet-valid checks.
/// * `failingPropertyIdentifier` - The property identifier associated with a validation failure.
/// * `details` - The validation failure details string buffer.
/// * `detailsLength` - The number of bytes written to the details buffer.
/// * `maxDetailsLength` - The maximum number of bytes that may be written to the details buffer.
///
/// # Returns
///
/// True if the pending certificate configuration is valid, otherwise false.
pub type FPCallbackValidateBACnetSCOperationalCertificate = extern "C" fn(u32, u32, *const u8, u32, *const u8, u32, *const u8, u32, i64, *mut u32, *mut std::os::raw::c_char, *mut u32, u32) -> bool;

/// The FPCallbackGenerateBACnetSCCertificateSigningRequest callback gets called when the CAS
/// BACnet Stack
/// needs the application to generate a new BACnet/SC key pair and PKCS#10 PEM CSR for
/// GENERATE_CSR_FILE.
///
/// The application owns the concrete key-generation and TLS implementation. The stack supplies
/// the currently
/// active operational certificate contents, if any, so the application can keep the generated CSR
/// subject aligned
/// with the active certificate subject when required by the BACnet/SC specification.
///
/// *Note:** This callback can only be used if the CAS BACnet Stack has been compiled with
/// STACK_OPTION_DATA_LINK_LAYER_SC
///
/// Registered with [`BACnetStack_RegisterCallbackGenerateBACnetSCCertificateSigningRequest`].
///
/// C declaration: `bool(*FPCallbackGenerateBACnetSCCertificateSigningRequest)(const uint32_t
/// deviceInstance, const uint32_t networkPortInstance, const uint8_t*
/// activeOperationalCertificateFileData, const uint32_t
/// activeOperationalCertificateFileDataLength, uint8_t* generatedCsrFileData, uint32_t*
/// generatedCsrFileDataLength, const uint32_t maxGeneratedCsrFileDataLength, char* details,
/// uint32_t* detailsLength, const uint32_t maxDetailsLength)`
///
/// # Arguments
///
/// * `deviceInstance` - The BACnet device instance that owns the BACnet/SC Network Port.
/// * `networkPortInstance` - The BACnet/SC Network Port object instance requesting CSR generation.
/// * `activeOperationalCertificateFileData` - The active Operational_Certificate_File contents, or NULL if none are active.
/// * `activeOperationalCertificateFileDataLength` - The length of the active operational certificate contents.
/// * `generatedCsrFileData` - The buffer that receives the generated PKCS#10 PEM CSR contents.
/// * `generatedCsrFileDataLength` - The number of bytes written to the CSR output buffer.
/// * `maxGeneratedCsrFileDataLength` - The maximum number of bytes that may be written to the CSR output buffer.
/// * `details` - The generation failure details string buffer.
/// * `detailsLength` - The number of bytes written to the details buffer.
/// * `maxDetailsLength` - The maximum number of bytes that may be written to the details buffer.
///
/// # Returns
///
/// True if CSR generation succeeded, otherwise false.
pub type FPCallbackGenerateBACnetSCCertificateSigningRequest = extern "C" fn(u32, u32, *const u8, u32, *mut u8, *mut u32, u32, *mut std::os::raw::c_char, *mut u32, u32) -> bool;

