pub fn BACnetStack_GetInfoLength() -> BACnetResult<u32> {
    unsafe {
        let function: libloading::Symbol<unsafe extern "C" fn() -> u32> =
            LIBRARY.get(b"BACnetStack_GetInfoLength")?;
        Ok(function())
    }
}

