/// which are
/// required and writable:
///
/// --------------------------------------------------------------------------------
/// Property Datatype Callback
/// --------------------------------------------------------------------------------
/// ObjectName CharacterString CallbackGetPropertyCharacterString
/// PresentValue BACnetChannelValue CallbackGetPropertyBool (the NULL-slot flag)
/// CallbackGetProperty<T>, T = presentValueDatatype
/// CallbackSetProperty<T> / CallbackSetPropertyNull
/// All of these are called with
/// propertyIdentifier = PriorityArray,
/// useArrayIndex = true, index 1..16.
/// LastPriority Unsigned CallbackGetPropertyUnsignedInteger
/// WriteStatus Enumerated CallbackGetPropertyEnumerated
/// OutOfService Boolean CallbackGetPropertyBool
/// ChannelNumber Unsigned16 CallbackGetPropertyUnsignedInteger
/// CallbackSetPropertyUnsignedInteger
/// ControlGroups Unsigned32 array CallbackGetPropertyUnsignedInteger
/// CallbackSetPropertyUnsignedInteger
/// Array index 0 is the element count.
/// AllowGroupDelayInhibit*
/// Boolean CallbackGetPropertyBool
/// Optional; enable it with BACnetStack_SetPropertyEnabled first.
/// --------------------------------------------------------------------------------
///
/// IMPORTANT: the WriteGroup service reads ChannelNumber and ControlGroups back through the
/// callbacks
/// above (ControlGroups at array index 0 for the count, then 1..N). An application that does not
/// serve them reports channel number 0 and an empty ControlGroups, and the Channel then never
/// matches
/// a WriteGroup request.
///
/// IMPORTANT: a PresentValue read whose 16 priority slots are all NULL falls back to a
/// RelinquishDefault read - and RelinquishDefault is not a Channel property, so that read returns
/// Error(PROPERTY, UNKNOWN_PROPERTY). Serve at least one priority slot.
