/// Sends a RegisterForeignDevice BVLL message to a specified BBMD (BACnet Broadcast Management
/// Device) to register as a foreign device on the BACnet IP network.
///
/// PRECONDITION: BACnetStack_RegisterCallbackGetSystemTime must have been registered first;
/// without a clock the time-to-live cannot be tracked and this returns false before sending.
///
/// A FALSE RETURN DOES NOT ALWAYS MEAN NOTHING HAPPENED: if connectionStringLength is not exactly
/// 6 (BACnet/IP), the Register-Foreign-Device frame has ALREADY been transmitted and only the
/// local
/// record failed, so the BBMD may hold an FDT entry this device is not tracking.
///
/// C declaration: `bool BACnetStack_SendRegisterForeignDevice(const uint32_t networkPortInstance,
/// const uint16_t timeToLive, const uint8_t* connectionString, const uint8_t
/// connectionStringLength)`
///
/// # Arguments
///
/// * `networkPortInstance` - (in) The IPv4 Network Port object instance to send on. Sprint 199 Phase 3 (#822/#556
///   Q4): new leading parameter - this whole BVLL/FD/BBMD family used to act on Network
///   Port instance 0 implicitly, with no way to name a different one.
/// * `timeToLive` - (in) The number of seconds within which this device must re-register with a BBMD or
///   risk it being purged from the BBMD's Foreign Device Table. THE STACK DOES NOT
///   AUTO-RENEW. It tracks the deadline locally and, when it passes, drops its own
///   foreign-device state and resets the Network Port's BACnetIPMode to normal. The host
///   must call this function again before the time-to-live expires. 0 is accepted but
///   expires on the next tick, cancelling the registration locally while the BBMD may still
///   hold the entry - it does NOT mean "forever".
/// * `connectionString` - (in) The connection string that represents the IP Address and Port of the BBMD to send
///   the RegisterForeignDevice message. Example: 0xC0, 0xA8, 0x01, 0x05, 0xBA, 0xC0 is
///   192.168.1.5:47808.
/// * `connectionStringLength` - (in) The number of bytes in the connection string.
///
/// # Returns
///
/// True if successfully sent, otherwise false.
pub fn BACnetStack_SendRegisterForeignDevice(
    networkPortInstance: u32,
    timeToLive: u16,
    connectionString: *const u8,
    connectionStringLength: u8,
) -> BACnetResult<bool> {
    unsafe {
        let function: libloading::Symbol<unsafe extern "C" fn(u32, u16, *const u8, u8) -> bool> =
            LIBRARY.get(b"BACnetStack_SendRegisterForeignDevice")?;
        Ok(function(networkPortInstance, timeToLive, connectionString, connectionStringLength))
    }
}

