/// initiatingDeviceInstance, const uint32_t subscriberProcessIdentifier, const uint16_t
/// monitoredObjectType, const uint32_t monitoredObjectInstance, const uint32_t timeRemaining,
/// const void* properties, const uint32_t propertyCount, const uint32_t propertiesLength, const
/// uint8_t* connectionString, const uint8_t connectionStringLength, const uint32_t
/// networkPortInstance, const bool broadcast, const uint16_t destinationNetwork, const uint8_t*
/// destinationAddress, const uint8_t destinationAddressLength)`
