/// # Arguments
///
/// * `uuid` - (in) The 16-octet device UUID. Must not be NULL.
/// * `uuidLength` - (in) The length of uuid. Must be EXACTLY 16; any other length is rejected. The
///   parameter exists for symmetry with the other BACnet/SC setters, not because other
///   lengths are legal.
///
/// # Returns
///
/// True if successfully set. False if uuid is NULL, uuidLength is not 16, a UUID has already
/// been set, the Device object sync failed, no BACnet/SC data link exists, or the stack was
/// built without STACK_OPTION_DATA_LINK_LAYER_SC.
pub fn BACnetStack_SetBACnetSCUuid(uuid: *const u8, uuidLength: u8) -> BACnetResult<bool> {
    unsafe {
        let function: libloading::Symbol<unsafe extern "C" fn(*const u8, u8) -> bool> =
            LIBRARY.get(b"BACnetStack_SetBACnetSCUuid")?;
        Ok(function(uuid, uuidLength))
    }
}

